style.css:
@-moz-document domain("bandlab.com") {
/* =====================================================
   BandLab Studio - Soft Pink Theme
   Track Color: #FFBFE0
   ===================================================== */

:root{
    --track:#FFBFE0;
    --track-border:#f4a8cd;
    --track-dark:#d98db5;
    --text:#3c2432;
}

/* ===========================
   LEFT TRACK PANEL
=========================== */

.mix-editor-track,
.mix-editor-track-header,
.mix-editor-track-header-content,
.mix-editor-track-controls,
.mix-editor-track-info,
.mix-editor-track-name{
    background:var(--track)!important;
}

.mix-editor-track-header{
    border-bottom:1px solid var(--track-border)!important;
}

.mix-editor-track *{
    color:var(--text)!important;
}

/* ===========================
   FX STRIP
=========================== */

.mix-editor-track-header-preset-button,
.mix-editor-track-header-preset-button.has-preset{
    background:var(--track)!important;
    border:none!important;
}

.mix-editor-track-header-preset-icon{
    background:none!important;
}

/* ===========================
   SLIDER
=========================== */

input[type="range"]{
    accent-color:var(--track)!important;
}

input[type="range"]::-webkit-slider-thumb{
    background:var(--track)!important;
}

input[type="range"]::-webkit-slider-runnable-track{
    background:var(--track-dark)!important;
}

.volume-slider,
.mix-editor-track-volume,
.slider,
.fader{
    accent-color:var(--track)!important;
}

/* ===========================
   AUDIO REGIONS
=========================== */

.mix-editor-region{
    background:var(--track)!important;
    border:1px solid var(--track-dark)!important;
}

.studio-region-title{
    background:#d89abf!important;
    color:var(--text)!important;
}

.mix-editor-region-name,
.mix-editor-region-name input{
    color:var(--text)!important;
}

/* Canvas background only */
.mix-editor-region-waveform{
    background:var(--track)!important;
}

/* ===========================
   SELECTED TRACK
=========================== */

.selected{
    box-shadow:0 0 0 2px var(--track-dark)!important;
}
}
